{
  "parts": {
    "situation": "When learners answer a question incorrectly, especially on phones, they currently see a red X and may leave.",
    "outcome": "I want learners leaving a wrong answer feeling smarter, not dumber, by understanding why their answer was wrong.",
    "why": "People may feel dumb and leave, and I want to reduce that drop-off.",
    "proof": "",
    "boundaries": "It has to work on phones. No gamification. I should not assume an AI chat panel or a rebuilt quiz engine is the solution."
  },
  "open": [
    "proof"
  ],
  "questions": [
    {
      "target": "proof",
      "text": "What would show you that a learner feels smarter after a wrong answer?"
    }
  ],
  "supports": [
    {
      "source": 1,
      "quote": "what I actually want is learners leaving a wrong answer feeling smarter not dumber.",
      "occurrence": 0
    },
    {
      "source": 1,
      "quote": "we already decided no gamification, that stays.",
      "occurrence": 0
    },
    {
      "source": 1,
      "quote": "it has to work on phones because thats where most people use it.",
      "occurrence": 0
    }
  ],
  "alternatives": [
    {
      "label": "Improve the explanation shown after an incorrect answer",
      "benefit": "Could directly address why the answer was wrong without adding a persistent chatbot.",
      "cost": "May not address tone or support follow-up questions.",
      "undo_cost": "Likely low."
    },
    {
      "label": "Improve the tone and wording of the incorrect-answer experience",
      "benefit": "Could reduce feelings of embarrassment or discouragement.",
      "cost": "A warmer tone alone may not build understanding.",
      "undo_cost": "Likely low."
    },
    {
      "label": "Add an AI tutor chat panel next to each question",
      "benefit": "Could provide interactive explanations and follow-up help.",
      "cost": "May become an unwanted chatbot and increase costs.",
      "undo_cost": "Potentially high if integrated broadly."
    }
  ],
  "misfits": [
    "Rebuilding the whole quiz engine is not yet connected to the confirmed need."
  ],
  "unresolved_notes": [
    "The reported drop-off around question 4 is unverified.",
    "It is unclear whether explanation quality, tone, or both are the main issue."
  ]
}
